def forward(groups):
    task_id = float(groups[0])
    stage_id = float(groups[1])
    tid = int(groups[2])
    result_bytes = int(groups[3])
    return {'stored': [task_id, stage_id, tid, result_bytes], 'layout': []}

def inverse(record):
    task_id, stage_id, tid, result_bytes = record['stored']
    return f"task {task_id:.1f} in stage {stage_id:.1f} (TID {tid}). {result_bytes} bytes result"
